{
  "id": "c275",
  "name": "1.01 Insured Certificates",
  "text": "Insured Certificates: The Class 1-A-3, Class 2-A-3 and Class 4-A-2 Certificates."
},
{
  "id": "c276",
  "name": "1.01 Insured Expenses",
  "text": "Insured Expenses: Expenses covered by an Insurance Policy or any other insurance policy with respect to the Mortgage Loans."
},
{
  "id": "c277",
  "name": "1.01 Interest Carry Forward Amount",
  "text": "Interest Carry Forward Amount: With respect to each Class of Senior Certificates and Mezzanine Certificates and each Distribution Date, the excess of (i) the Current Interest for such Class with respect to prior Distribution Dates over (ii) the amount actually distributed to such Class with respect to interest on such prior Distribution Dates."
},

{
  "id": "c278",
  "name": "1.01 Interest Funds",
  "text": "Interest Funds: With respect to any Distribution Date and Loan Group, the sum of (i) the Interest Remittance Amount for such Loan Group for such Distribution Date and (ii) the Deferred Interest for all Mortgage Loans in such Loan Group for the related Due Date up to the Principal Remittance Amount for such Loan Group for such Distribution Date."
},
{
  "id": "c279",
  "name": "1.01 Interest Only Certificates",
  "text": "Interest Only Certificates: As defined in the Preliminary Statement."
},
{
  "id": "c280",
  "name": "1.01 Interest Remittance Amount",
  "text": "Interest Remittance Amount: With respect to the Mortgage Loans in a Loan Group and any Distribution Date, (x) the sum, without duplication, of (i) all scheduled interest on the Mortgage Loans in that Loan Group due on the related Due Date and received on or prior to the related Determination Date, less the related Servicing Fees, Credit Risk Manager Fees and any payments made in respect of premiums on lender paid insurance mortgage loans, (ii) all interest on Principal Prepayments on the Mortgage Loans in that Loan Group, other than Prepayment Interest Excess, (iii) all Advances relating to interest with respect to the Mortgage Loans in that Loan Group, (iv) all Compensating Interest with respect to such Mortgage Loans in that Loan Group and (v) Liquidation Proceeds with respect to the Mortgage Loans in that Loan Group during the related Prepayment Period (to the extent such Liquidation Proceeds relate to interest), less (y) all reimbursements to the Master Servicer since the immediately preceding Due Date for Nonrecoverable Advances of interest previously made allocable to such Loan Group."
},
{
  "id": "c281",
  "name": "1.01 Issuing Entity",
  "text": "Issuing Entity: As defined in Section 2.01(c)."
},
{
  "id": "c282",
  "name": "1.01 Late Payment Rate",
  "text": "Late Payment Rate: The lesser of (a) the greater of (i) the per annum rate of interest publicly announced from time to time by JPMorgan Chase Bank, N.A. as its prime or base lending rate (any change in such rate of interest to be effective on the date such change is announced by JPMorgan Chase Bank, N.A.) plus 2.00%, and (ii) the then applicable highest rate of interest on the Insured Notes and (b) the maximum rate permissible under applicable usury or similar laws limiting interest rates as determined by the Class A Note Insurer. The Late Payment Rate shall be computed on the basis of the actual number of days elapsed over a year of 360 days."
},
{
  "id": "c283",
  "name": "1.01 Latest Possible Maturity Date",
  "text": "Latest Possible Maturity Date: The Distribution Date following the third anniversary of the scheduled maturity date of the Mortgage Loan having the latest scheduled maturity date as of the Cut-off Date."
},
{
  "id": "c284",
  "name": "1.01 LIBOR",
  "text": "LIBOR: As to any Distribution Date, the arithmetic mean of the London Interbank offered rate quotations for one month U.S. Dollar deposits, as determined by the Trust Administrator in accordance with Section 4.10."
},
{
  "id": "c285",
  "name": "1.01 LIBOR Business Day",
  "text": "LIBOR Business Day: Any day other than (i) a Saturday or a Sunday or (ii) a day on which banking institutions in the State of New York or in the City of London, England are required or authorized by law to be closed."
},
{
  "id": "c286",
  "name": "1.01 LIBOR Determination Date",
  "text": "LIBOR Determination Date: As to any Distribution Date, other than the first Distribution Date, and any Class of LIBOR Certificates, the second LIBOR Business Day prior to the beginning of the applicable Accrual Period for such Class and such Distribution Date."
},
{
  "id": "c287",
  "name": "1.01 Liquidated Mortgage Loan",
  "text": "Liquidated Mortgage Loan: With respect to any Distribution Date, (i) a defaulted Mortgage Loan (including any REO Property) which was liquidated in the calendar month preceding the month of such Distribution Date and as to which the applicable Servicer or the Master Servicer, as the case may be, has determined (in accordance with the applicable Servicing Agreement and this Agreement) that it has received all amounts it expects to receive in connection with the liquidation of such Mortgage Loan, including the final disposition of an REO Property or (ii) any Mortgage Loan that becomes 180 days or more delinquent in the calendar month preceding the month of such Distribution Date."
},
{
  "id": "c288",
  "name": "1.01 Liquidation Proceeds",
  "text": "Liquidation Proceeds: Amounts, including Insurance Proceeds, received in connection with the partial or complete liquidation of defaulted Mortgage Loans, whether through trustee’s sale, foreclosure sale or otherwise or amounts received in connection with any condemnation or partial release of a Mortgaged Property and any other proceeds received in connection with an REO Property, less the sum of related unreimbursed Servicing Fees and Servicing Advances."
},
{
  "id": "c289",
  "name": "1.01 Loan-to-Value Ratio",
  "text": "Loan-to-Value Ratio: With respect to any Mortgage Loan and as to any date of determination, the fraction (expressed as a percentage) the numerator of which is the principal balance of the related Mortgage Loan at such date of determination and the denominator of which is the Appraised Value of the related Mortgaged Property. For purposes of representation (xxxi) of Schedule II, the Loan-to-Value Ratio will be the loan-to-value ratio calculated in accordance with applicable state laws regarding primary mortgage insurance."
},
{
  "id": "c290",
  "name": "1.01 Loan Group",
  "text": "Loan Group: Any of the Group 1 Loans, the Group 2 Loans, the Group 3 Loans or the Group 4 Loans, as applicable."
},
{
  "id": "c291",
