{
  "id": "c418",
  "name": "1.01 Servicing Fee",
  "text": "Servicing Fee: As to each Mortgage Loan and any Distribution Date, an amount payable out of each full payment of interest received on such Mortgage Loan and equal to one twelfth of the Servicing Fee Rate multiplied by the Principal Balance of such Mortgage Loan as of the Due Date in the month immediately preceding the month in which such Distribution Date occurs (after giving effect to any Scheduled Payments due on such Mortgage Loan on such Due Date)."
},
{
  "id": "c419",
  "name": "1.01 Servicing Fee Rate",
  "text": "Servicing Fee Rate: With respect to each Mortgage Loan, the per annum rate set forth on the Mortgage Loan Schedule."
},
{
  "id": "c420",
  "name": "1.01 Servicing Function Participant",
  "text": "Servicing Function Participant: Any Sub-Servicer or Subcontractor of a Servicer, the Master Servicer, the Custodian or the Trust Administrator, respectively."
},
{
  "id": "c421",
  "name": "1.01 Sixty-Day Delinquency Rate",
  "text": "Sixty-Day Delinquency Rate: With respect to any Distribution Date on or after the Stepdown Date, a fraction, expressed as a percentage, the numerator of which is the aggregate Stated Principal Balance for such Distribution Date of all Loans that were 60 or more days Delinquent as of the close of business on the last day of the calendar month preceding such Distribution Date (including Loans in foreclosure, bankruptcy and REO Properties) and the denominator of which is the aggregate Stated Principal Balance for such Distribution Date of the Loans as of the related Due Date (after giving effect to principal prepayments in the Prepayment Period related to that prior Due Date)."
},
{
  "id": "c422",
